class Solution {
  public int maxXorSubsequences(int[] nums) {
    int[] basis = new int[31];
    for (int x : nums) {
      for (int b = 30; b >= 0 && x != 0; b--) {
        if ((x >> b & 1) == 0) continue;
        if (basis[b] == 0) {
          basis[b] = x;
          break;
        }
        x ^= basis[b];
      }
    }
    int best = 0;
    for (int b = 30; b >= 0; b--) if ((best ^ basis[b]) > best) best ^= basis[b];
    return best;
  }
}
